const email = $input.first().json;

// Fonction pour extraire nom et prénom du champ "from"
function extractNameFromEmail(fromString) {
    if (!fromString) return { nom: null, prenom: null };

    // Format: "Ikrame Baskane <ikramebaskane8@gmail.com>"
    // OU: "Marie Durand <marie.durand@email.com>"

    // Extraire la partie avant <email>
    const namePart = fromString.split('<')[0].trim();

    if (!namePart) return { nom: null, prenom: null };

    // Séparer par espace
    const parts = namePart.split(' ');

    if (parts.length === 1) {
        // Un seul mot → mettre dans nom
        return { nom: parts[0], prenom: null };
    } else if (parts.length === 2) {
        // Deux mots → prénom nom
        return { nom: parts[1], prenom: parts[0] };
    } else {
        // Plus de 2 mots → premier = prénom, dernier = nom
        return { 
            nom: parts[parts.length - 1], 
            prenom: parts.slice(0, -1).join(' ') 
        };
    }
}

// Extraire email
function extractEmail(fromString) {
    if (!fromString) return 'inconnu@email.com';

    // Chercher pattern <email>
    const emailMatch = fromString.match(/<([^>]+)>/);
    if (emailMatch && emailMatch[1]) {
        return emailMatch[1].trim();
    }

    // Si pas de <>, vérifier si c'est directement un email
    if (fromString.includes('@')) {
        return fromString.trim();
    }

    return 'inconnu@email.com';
}

