// Nœud JavaScript pour nettoyer et préparer pour embedding

function cleanEmailMessage(message) {
  if (!message) return '';

  // Trouver le début du vrai message (après l'en-tête technique)
  const bonjourIndex = message.toLowerCase().indexOf('bonjour');
  let cleaned = bonjourIndex > 0 ? message.substring(bonjourIndex) : message;

  // Nettoyer les caractères bizarres
  cleaned = cleaned.replace(/â¯/g, ' ');

  return cleaned.trim();
}

function sanitizeForEmbedding(text) {
  if (!text) return '';

  // 1. Échapper UNIQUEMENT les guillemets doubles pour JSON
  let sanitized = text.replace(/"/g, '\\"');

  // 2. Remplacer tous les sauts de ligne par des espaces
  sanitized = sanitized.replace(/[\n\r\t]/g, ' ');

  // 3. Supprimer les caractères de contrôle (optionnel)
  sanitized = sanitized.replace(/[\x00-\x1F\x7F]/g, ' ');

  // 4. Supprimer les espaces multiples
  sanitized = sanitized.replace(/\s+/g, ' ');

  return sanitized.trim();
}

// Main
const inputData = $input.first().json;

// Nettoyer le message
const cleanMessage = cleanEmailMessage(inputData.message);

// Nettoyer pour embedding
const forEmbedding = sanitizeForEmbedding(cleanMessage);

// Créer le payload JSON complet pour l'API
const embeddingPayload = {
  model: "models/text-embedding-004",
  content: {
    parts: [
      {
        text: forEmbedding
      }
    ]
  }
};

// Retourner le résultat
return [{
  json: {
    ...inputData,
    page_content: forEmbedding,
    // Payload déjà formaté en JSON string
    embedding_json: JSON.stringify(embeddingPayload),
    // Pour debug
  }
}];

// Nœud JavaScript - Formater embedding pour PostgreSQL

const input = $input.first().json;

// 1. Récupérer l'embedding
const embeddingValues = input.embedding?.values || [];

// 2. Vérifier que c'est un array
if (!Array.isArray(embeddingValues)) {
  throw new Error("L'embedding n'est pas un array !");
}

// 3. Convertir en format PostgreSQL ARRAY string
// Format: {0.011800998,0.004005518,0.04419434,...}
const pgArrayString = `[${embeddingValues.join(',')}]`;

// 4. Vérifier la longueur (768 pour votre modèle)
const expectedLength = 768;
const actualLength = embeddingValues.length;

// 5. Préparer les données pour PostgreSQL
return [{
  json: {
    // Données pour l'insertion

    // ⭐ EMBEDDING FORMATÉ POUR POSTGRESQL ⭐
    embedding_pg: pgArrayString,

    // Valeurs par défaut
    categorie: "non_categorise",
    urgence: "medium",
    statut: "nouvelle",

    // Métadonnées pour debug
    embedding_length: actualLength,
    is_correct_length: actualLength === expectedLength,
    first_3_values: embeddingValues.slice(0, 3),
    pg_format_sample: pgArrayString.substring(0, 50) + "..."
  }
}];

